def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r, row in enumerate(grid):
        bg = max(set(row), key=row.count)
        # Identify a foreground-colored regular sequence along a row. Continue
        # its established phase through the remaining tail as color 1.
        for period in range(2, 7):
            phases = {}
            for c, v in enumerate(row):
                if v != bg:
                    phases.setdefault(c % period, set()).add(v)
            candidates = [(p, next(iter(vs))) for p,vs in phases.items() if len(vs)==1 and sum(row[c] == next(iter(vs)) for c in range(w) if c%period==p) >= 3]
            if candidates:
                # only continue when phase is clear and the visible pattern has a long enough run
                p, val = max(candidates, key=lambda x: sum(1 for c in range(w) if c%period==x[0] and row[c]==x[1]))
                occ = [c for c in range(w) if c%period==p and row[c]==val]
                if len(occ) >= 4 and occ[-1] < w-2:
                    for c in range(occ[-1]+1, w):
                        if c%period==p and row[c]==bg:
                            out[r][c] = 1
                    break
    return out
