def transform(grid):
    out = [row[:] for row in grid]
    # Recolor the blank continuation after the final foreground mark in the
    # row of the upper motif that terminates before the right edge.
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    active = [r for r,row in enumerate(grid) if any(v != bg for v in row)]
    if not active:
        return out
    top_block_end = active[0]
    while top_block_end + 1 < h and any(v != bg for v in grid[top_block_end+1]):
        top_block_end += 1
    # Within the upper motif, select the row with the shortest foreground reach
    # among its lower patterned rows; its trailing blank continuation is 1.
    rows = [r for r in active if r <= top_block_end]
    if rows:
        r = min(rows, key=lambda y: max((c for c,v in enumerate(grid[y]) if v != bg), default=-1))
        end = max(c for c,v in enumerate(grid[r]) if v != bg)
        for c in range(end+1,w):
            if grid[r][c] == bg:
                out[r][c] = 1
    return out

