def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==v and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if any(x == w-1 for y,x in comp):
                # recolor this edge-touching foreground component
                for y,x in comp:
                    out[y][x] = 1
    return out
