def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Extend established periodic foreground motifs to the right; newly inferred
    # motif cells are marked with color 1, as in the demonstrations.
    for r, row in enumerate(grid):
        colors = set(row)
        bg = max(colors, key=row.count)
        fg = [c for c,v in enumerate(row) if v != bg]
        if len(fg) < 4:
            continue
        best = None
        for period in range(2, 7):
            # Find a same-color arithmetic run of at least four marks.
            for start in fg:
                for color in colors - {bg}:
                    seq = [c for c in range(start, w) if row[c] == color and (c-start) % period == 0]
                    if len(seq) >= 4:
                        run = []
                        c = start
                        while c < w and row[c] == color:
                            run.append(c); c += period
                        if len(run) >= 4 and (best is None or len(run) > best[0]):
                            best = (len(run), period, color, run[-1])
        if best:
            _, period, color, last = best
            c = last + period
            while c < w:
                if row[c] == bg:
                    out[r][c] = 1
                c += period
    return out
